25	// Betweenness centrality from a single source (Brandes' algorithm).
26	//
27	// The forward sweep is a BFS that also counts, for every vertex, the number of
28	// shortest paths from the source that reach it (NumPaths).  Every BFS frontier
29	// is remembered in Levels.  The backward sweep then walks the levels from the
30	// deepest one back to the source, accumulating dependency scores along the
31	// reverse of the BFS DAG.  As in Ligra, the dependency values are carried
32	// through the backward sweep pre-multiplied by 1/NumPaths, which turns the
33	// per-edge scaling of Brandes' recurrence into a single add per vertex; the
34	// scaling is undone in one final pass over the array.
35	#include "ligra.h"
36	#include <vector>
37	#include <cmath>
38	#include <limits>
39	#include <iomanip>
40	
41	typedef double fType;
42	
43	// Forward (BFS) phase: adds the path count of the source of an edge into the
44	// path count of its destination.  Returns true exactly when the destination
45	// had no paths before, i.e. when it should join the next frontier.
46	struct BC_F {
47	  fType* NumPaths;
48	  bool* Visited;
49	  BC_F(fType* _NumPaths, bool* _Visited) :
50	    NumPaths(_NumPaths), Visited(_Visited) {}
51	  inline bool update(uintE s, uintE d) { //Update
52	    fType oldV = NumPaths[d];
53	    NumPaths[d] += NumPaths[s];
54	    return oldV == 0.0;
55	  }
56	  inline bool updateAtomic(uintE s, uintE d) { //atomic Update, basically an add
57	    volatile fType oldV, newV;
58	    do {
59	      oldV = NumPaths[d]; newV = oldV + NumPaths[s];
60	    } while(!CAS(&NumPaths[d],oldV,newV));
61	    return oldV == 0.0;
62	  }
63	  //only vertices that have not been reached by the BFS yet are of interest
64	  inline bool cond(uintE d) { return Visited[d] == 0; }
65	};
66	
67	// Backward phase: same add-and-report-whether-it-was-zero pattern as BC_F, but
68	// on the dependency scores instead of the path counts.
69	struct BC_Back_F {
70	  fType* Dependencies;
71	  bool* Visited;
72	  BC_Back_F(fType* _Dependencies, bool* _Visited) :
73	    Dependencies(_Dependencies), Visited(_Visited) {}
74	  inline bool update(uintE s, uintE d) { //Update
75	    fType oldV = Dependencies[d];
76	    Dependencies[d] += Dependencies[s];
77	    return oldV == 0.0;
78	  }
79	  inline bool updateAtomic(uintE s, uintE d) { //atomic Update
80	    volatile fType oldV, newV;
81	    do {
82	      oldV = Dependencies[d]; newV = oldV + Dependencies[s];
83	    } while(!CAS(&Dependencies[d],oldV,newV));
84	    return oldV == 0.0;
85	  }
86	  //levels that have already been processed are excluded
87	  inline bool cond(uintE d) { return Visited[d] == 0; }
88	};
89	
90	//vertex map function to mark the vertices of a new frontier as visited
91	struct BC_Vertex_F {
92	  bool* Visited;
93	  BC_Vertex_F(bool* _Visited) : Visited(_Visited) {}
94	  inline bool operator () (uintE i) {
95	    Visited[i] = 1;
96	    return 1;
97	  }
98	};
99	
100	// Vertex map function used on the backward phase.  It closes off the level that
101	// is about to be pushed backwards (so that the following edgeMap cannot write
102	// into it, or into any deeper level) and adds this vertex' own 1/NumPaths term
103	// to its dependency score.
104	struct BC_Back_Vertex_F {
105	  bool* Visited;
106	  fType* Dependencies, *inverseNumPaths;
107	  BC_Back_Vertex_F(bool* _Visited, fType* _Dependencies, fType* _inverseNumPaths) :
108	    Visited(_Visited), Dependencies(_Dependencies),
109	    inverseNumPaths(_inverseNumPaths) {}
110	  inline bool operator () (uintE i) {
111	    Visited[i] = 1;
112	    Dependencies[i] += inverseNumPaths[i];
113	    return 1;
114	  }
115	};
116	
117	template <class vertex>
118	void Compute(graph<vertex>& GA, commandLine P) {
119	  long start = P.getOptionLongValue("-r",0);
120	  const long n = GA.n;
121	
122	  //number of shortest paths from start to each vertex
123	  fType* NumPaths = newA(fType,n);
124	  {parallel_for(long i=0;i<n;i++) NumPaths[i] = 0.0;}
125	  NumPaths[start] = 1.0;
126	
127	  bool* Visited = newA(bool,n);
128	  {parallel_for(long i=0;i<n;i++) Visited[i] = 0;}
129	  Visited[start] = 1;
130	
131	  // Levels[r] is the set of vertices at BFS distance r from start.  The
132	  // frontiers are owned by this vector: they are read again by the backward
133	  // sweep and freed in a single pass at the end, so that no vertexSubset is
134	  // deleted twice (and any array that edgeMap materializes inside a frontier,
135	  // e.g. its dense representation, is freed too).
136	  vector<vertexSubset> Levels;
137	  Levels.push_back(vertexSubset(n,start));
138	
139	  long round = 0;
140	  while(!Levels[round].isEmpty()) {
141	    round++;
142	    //accumulate path counts into the next frontier
143	    vertexSubset output = edgeMap(GA, Levels[round-1], BC_F(NumPaths,Visited));
144	    vertexMap(output, BC_Vertex_F(Visited));
145	    Levels.push_back(output);
146	  }
147	  //Levels[round] is the empty frontier that terminated the BFS
148	
149	  fType* Dependencies = newA(fType,n);
150	  {parallel_for(long i=0;i<n;i++) Dependencies[i] = 0.0;}
151	
152	  //invert NumPaths in place; unreachable vertices become infinite
153	  fType* inverseNumPaths = NumPaths;
154	  {parallel_for(long i=0;i<n;i++) inverseNumPaths[i] = 1/inverseNumPaths[i];}
155	
156	  //Visited is reused by the backward sweep to mark the levels already done
157	  {parallel_for(long i=0;i<n;i++) Visited[i] = 0;}
158	
159	  //the backward sweep follows edges against their forward direction
160	  GA.transpose();
161	
162	  for(long r=round-1;r>=0;r--) {
163	    vertexMap(Levels[r], BC_Back_Vertex_F(Visited,Dependencies,inverseNumPaths));
164	    //level 0 holds only start, whose score is not propagated any further
165	    if(r > 0) {
166	      edgeMap(GA, Levels[r], BC_Back_F(Dependencies,Visited), GA.m/20, no_output);
167	    }
168	  }
169	
170	  //undo the 1/NumPaths scaling to obtain the dependency scores
171	  {parallel_for(long i=0;i<n;i++) {
172	    //a vertex the BFS never reached lies on no shortest path at all, and its
173	    //infinite inverseNumPaths would otherwise produce a NaN here
174	    Dependencies[i] = (inverseNumPaths[i] == numeric_limits<fType>::infinity())
175	      ? 0.0
176	      : (Dependencies[i]-inverseNumPaths[i])/inverseNumPaths[i];
177	  }}
178	
179	  fType maxScore = sequence::reduce<fType>(Dependencies,n,maxF<fType>());
180	  fType sum = sequence::plusReduce(Dependencies,n);
181	  cout << "BC rounds: " << round << endl;
182	  cout << setprecision(10) << "BC max score: " << maxScore << endl;
183	  cout << setprecision(10) << "BC sum: " << sum << endl;
184	
185	  for(long i=0;i<=round;i++) Levels[i].del();
186	  free(Dependencies); free(Visited); free(inverseNumPaths);
187	}
